-- GET TO IT — reject a parameter that is missing where a value list is required.
--
-- A guard such as `if p_decision not in ('approved', 'rejected') then` is NULL,
-- not false, when the parameter is missing, so the check never runs and the NULL
-- travels into the statement that follows. Each guard now rejects a missing
-- parameter explicitly instead of relying on a column constraint to catch it.
--
-- Validation only: these guards decide whether input is well formed, not whether
-- the caller may act.

-- Generated by scripts/sql-role-guard-audit.mjs, so the check and the fix share one rule set.

create or replace function public.api_create_deployment_proposal(
  p_key_hash text,
  p_project_id uuid,
  p_target text,
  p_plan jsonb,
  p_plan_hash text,
  p_snapshot_version integer,
  p_digest text,
  p_snapshot jsonb,
  p_idempotency_key text,
  p_request_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_guard jsonb;
  v_idem jsonb;
  v_project public.app_projects;
  v_deployment_id uuid;
  v_response jsonb;
begin
  v_guard := public.api_guard(
    p_key_hash, 'deployments:propose', 'deployments.propose', p_project_id
  );
  if not (v_guard ->> 'ok')::boolean then
    return v_guard;
  end if;

  if p_idempotency_key is null
     or p_idempotency_key !~ '^[A-Za-z0-9_-]{8,128}$' then
    return jsonb_build_object(
      'ok', false, 'code', 'idempotency_key_required',
      'message', 'Send an Idempotency-Key header of 8 to 128 letters, digits, underscores or dashes.',
      'request_id', v_guard ->> 'request_id'
    );
  end if;

  v_idem := public.api_idem_start(
    (v_guard ->> 'key_id')::uuid,
    'deployments.propose:' || p_project_id::text,
    p_idempotency_key, p_request_hash
  );
  if v_idem ->> 'state' = 'conflict' then
    return jsonb_build_object(
      'ok', false, 'code', 'idempotency_conflict',
      'message', 'That Idempotency-Key was already used with a different request body.',
      'request_id', v_guard ->> 'request_id'
    );
  end if;
  if v_idem ->> 'state' = 'replay' then
    return (v_idem -> 'response') || jsonb_build_object(
      'replayed', true, 'request_id', v_guard ->> 'request_id'
    );
  end if;

  if (p_target is null or p_target not in ('preview', 'production')) then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_request',
      'message', 'Choose preview or production.',
      'request_id', v_guard ->> 'request_id'
    );
  end if;
  if jsonb_typeof(p_plan) <> 'object'
     or jsonb_typeof(p_snapshot) <> 'array'
     or jsonb_array_length(p_snapshot) not between 1 and 60 then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_request',
      'message', 'A proposal needs one source snapshot and the resolved plan.',
      'request_id', v_guard ->> 'request_id'
    );
  end if;
  if p_plan_hash is null or p_plan_hash !~ '^[a-f0-9]{64}$'
     or p_digest is null or p_digest !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object(
      'ok', false, 'code', 'invalid_request',
      'message', 'The plan and source fingerprints must be SHA-256 hex values.',
      'request_id', v_guard ->> 'request_id'
    );
  end if;

  select * into v_project
    from public.app_projects
   where id = p_project_id and user_id = (v_guard ->> 'user_id')::uuid;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;

  if p_snapshot_version <> v_project.current_version or v_project.current_version < 1 then
    return jsonb_build_object(
      'ok', false, 'code', 'stale_source',
      'message', 'The project changed after the plan inputs were read. Request the proposal again.',
      'request_id', v_guard ->> 'request_id'
    );
  end if;

  -- status is hard-coded to draft: the API can propose, never approve.
  insert into public.app_deployments (
    project_id, user_id, target, snapshot_version, snapshot_digest,
    snapshot, plan, plan_hash, status, checks, migration_state
  )
  values (
    p_project_id, v_project.user_id, p_target, p_snapshot_version, p_digest,
    p_snapshot, p_plan, p_plan_hash, 'draft', '[]'::jsonb, 'not_applied'
  )
  returning id into v_deployment_id;

  insert into public.app_deployment_events
    (deployment_id, project_id, user_id, kind, detail)
  values (
    v_deployment_id, p_project_id, v_project.user_id, 'proposal',
    'A developer API credential requested a draft deployment plan. No approval or deployment occurred.'
  );

  v_response := jsonb_build_object(
    'ok', true,
    'proposal', jsonb_build_object(
      'id', v_deployment_id,
      'project_id', p_project_id,
      'target', p_target,
      'status', 'draft',
      'approval_required', true,
      'approved', false,
      'snapshot_version', p_snapshot_version,
      'snapshot_digest', p_digest,
      'plan_hash', p_plan_hash,
      'plan', p_plan,
      'notice', 'This is a proposal only. It cannot deploy. The project owner must review it, run pre-deploy checks and type DEPLOY in the web app.'
    ),
    'request_id', v_guard ->> 'request_id'
  );

  perform public.api_idem_store(
    (v_guard ->> 'key_id')::uuid,
    'deployments.propose:' || p_project_id::text,
    p_idempotency_key, p_request_hash, v_response, 201
  );

  return v_response || jsonb_build_object('replayed', false);
end;
$$;

create or replace function public.composio_complete_action(
  p_action_id uuid,
  p_status text,
  p_result jsonb,
  p_provider_ref text,
  p_error_code text,
  p_error_message text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_action public.app_composio_actions;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated', 'message', 'Sign in again.');
  end if;

  if (p_status is null or p_status not in ('succeeded', 'failed', 'uncertain')) then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'message', 'Unknown completion status.');
  end if;

  if p_result is not null and octet_length(p_result::text) > 32768 then
    return jsonb_build_object('ok', false, 'code', 'result_too_large', 'message', 'That result is too large to store.');
  end if;

  update public.app_composio_actions
     set status = p_status,
         result = p_result,
         provider_ref = left(p_provider_ref, 200),
         error_code = left(p_error_code, 80),
         error_message = left(p_error_message, 800),
         finished_at = now(),
         updated_at = now()
   where id = p_action_id and user_id = v_uid and status = 'executing'
  returning * into v_action;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'invalid_state', 'message', 'That action is not executing.');
  end if;

  return jsonb_build_object('ok', true, 'status', v_action.status);
end;
$$;

create or replace function public.composio_disconnect(
  p_connection_id uuid,
  p_mode text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_connection public.app_composio_connections;
  v_status text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated', 'message', 'Sign in again.');
  end if;

  if (p_mode is null or p_mode not in ('revoke', 'remove')) then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'message', 'Choose revoke or remove.');
  end if;

  v_status := case when p_mode = 'revoke' then 'revoked' else 'removed' end;

  update public.app_composio_connections
     set status = v_status,
         revoked_at = now(),
         updated_at = now()
   where id = p_connection_id and user_id = v_uid
  returning * into v_connection;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'That connection is not available.');
  end if;

  update public.app_composio_tool_grants
     set enabled = false, updated_at = now()
   where connection_id = v_connection.id and user_id = v_uid;

  update public.app_composio_actions
     set status = 'cancelled', finished_at = now(), updated_at = now()
   where connection_id = v_connection.id
     and user_id = v_uid
     and status in ('proposed', 'approved');

  return jsonb_build_object('ok', true, 'status', v_status);
end;
$$;

create or replace function public.composio_finish_auth(
  p_attempt_id uuid,
  p_state text,
  p_status text,
  p_connected_account_id text,
  p_account_label text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_attempt public.app_composio_auth_attempts;
  v_connection public.app_composio_connections;
  v_label text := left(btrim(coalesce(p_account_label, '')), 120);
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated', 'message', 'Sign in again.');
  end if;

  select * into v_attempt
    from public.app_composio_auth_attempts
   where id = p_attempt_id and user_id = v_uid
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'That authorization attempt is not available.');
  end if;

  if v_attempt.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'invalid_state', 'message', 'That authorization attempt was already used.');
  end if;

  if v_attempt.expires_at <= now() then
    update public.app_composio_auth_attempts
       set status = 'expired', completed_at = now()
     where id = v_attempt.id;
    return jsonb_build_object('ok', false, 'code', 'expired', 'message', 'That authorization attempt expired. Start again.');
  end if;

  if p_state is null or p_state !~ '^[a-f0-9]{64}$'
     or v_attempt.state_hash <> encode(sha256(convert_to(p_state, 'UTF8')), 'hex') then
    return jsonb_build_object('ok', false, 'code', 'invalid_state', 'message', 'That authorization response did not match this attempt.');
  end if;

  if p_status = 'cancelled' then
    update public.app_composio_auth_attempts
       set status = 'cancelled', completed_at = now()
     where id = v_attempt.id;
    return jsonb_build_object('ok', true, 'status', 'cancelled');
  end if;

  if p_status = 'failed' then
    update public.app_composio_auth_attempts
       set status = 'failed', completed_at = now(),
           error = left(coalesce(p_account_label, 'Authorization failed at the provider.'), 300)
     where id = v_attempt.id;
    return jsonb_build_object('ok', false, 'code', 'authorization_failed', 'message', 'The provider did not complete the connection.');
  end if;

  if (p_status is null or p_status <> 'completed') then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'message', 'Unknown authorization result.');
  end if;

  if p_connected_account_id is null
     or p_connected_account_id !~ '^ca_[A-Za-z0-9_-]{3,80}$' then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'message', 'The provider returned no usable connected account.');
  end if;

  insert into public.app_composio_connections
    (user_id, project_id, toolkit, connected_account_id, account_label, status, last_verified_at)
  values
    (v_uid, v_attempt.project_id, v_attempt.toolkit, p_connected_account_id, v_label, 'active', now())
  on conflict (project_id, toolkit, connected_account_id) do update
    set account_label = excluded.account_label,
        status = 'active',
        last_verified_at = now(),
        revoked_at = null,
        updated_at = now()
    where app_composio_connections.user_id = v_uid
  returning * into v_connection;

  if v_connection.id is null then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'That connected account is already linked to another account.');
  end if;

  update public.app_composio_auth_attempts
     set status = 'completed', connected_account_id = p_connected_account_id, completed_at = now()
   where id = v_attempt.id;

  return jsonb_build_object(
    'ok', true,
    'status', 'completed',
    'connection', jsonb_build_object(
      'id', v_connection.id,
      'project_id', v_connection.project_id,
      'toolkit', v_connection.toolkit,
      'account_label', v_connection.account_label,
      'status', v_connection.status,
      'connected_at', v_connection.created_at
    )
  );
end;
$$;

create or replace function public.composio_update_connection(
  p_connection_id uuid,
  p_status text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_connection public.app_composio_connections;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated', 'message', 'Sign in again.');
  end if;

  if (p_status is null or p_status not in ('active', 'expired')) then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'message', 'That connection status cannot be set directly.');
  end if;

  update public.app_composio_connections
     set status = p_status,
         last_verified_at = now(),
         revoked_at = case when p_status = 'expired' then now() else revoked_at end,
         updated_at = now()
   where id = p_connection_id and user_id = v_uid
  returning * into v_connection;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'That connection is not available.');
  end if;

  return jsonb_build_object('ok', true, 'status', v_connection.status);
end;
$$;

create or replace function public.create_app_build_task(
  p_project_id uuid,
  p_title text,
  p_description text,
  p_assignee_kind text,
  p_assignee_id uuid,
  p_agent_role text,
  p_scope_paths jsonb default '[]'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_role text := public.app_project_role(p_project_id);
  v_task uuid;
  v_path jsonb;
begin
  if v_role is null or v_role not in ('owner', 'maintainer', 'contributor') then
    raise exception 'contributor access required';
  end if;
  if p_title is null or char_length(btrim(p_title)) not between 3 and 200 then
    raise exception 'task title must be 3 to 200 characters';
  end if;
  if p_description is null or char_length(p_description) > 2000 then
    raise exception 'task description is too long';
  end if;
  if (p_assignee_kind is null or p_assignee_kind not in ('human', 'agent')) then raise exception 'invalid assignee kind'; end if;
  if p_assignee_kind = 'agent' and v_role not in ('owner', 'maintainer') then
    raise exception 'only a maintainer or owner can assign an agent';
  end if;
  if p_assignee_kind = 'agent' and (p_agent_role is null or p_agent_role not in ('coordinator', 'frontend', 'backend', 'data', 'qa', 'security')) then
    raise exception 'invalid agent role';
  end if;
  if p_assignee_kind = 'human' and p_assignee_id is not null
     and public.app_project_role(p_project_id, p_assignee_id) is null then
    raise exception 'the assignee is not a project member';
  end if;
  if jsonb_typeof(p_scope_paths) <> 'array' or jsonb_array_length(p_scope_paths) > 12 then
    raise exception 'invalid task scope';
  end if;
  for v_path in select * from jsonb_array_elements(p_scope_paths)
  loop
    if jsonb_typeof(v_path) <> 'string'
       or not exists (select 1 from public.app_files f where f.project_id = p_project_id and f.path = v_path #>> '{}') then
      raise exception 'task scope must reference existing project files';
    end if;
  end loop;

  insert into public.app_build_tasks
    (project_id, title, description, assignee_kind, assignee_id, agent_role, scope_paths, created_by)
  values
    (p_project_id, left(btrim(p_title), 200), left(coalesce(p_description, ''), 2000),
     p_assignee_kind, case when p_assignee_kind = 'human' then p_assignee_id else null end,
     case when p_assignee_kind = 'agent' then p_agent_role else null end,
     coalesce(p_scope_paths, '[]'::jsonb), v_actor)
  returning id into v_task;

  return v_task;
end;
$$;

create or replace function public.create_app_integration(
  p_project_id uuid,
  p_kind text,
  p_name text,
  p_config jsonb,
  p_allowed_operations jsonb,
  p_mapping jsonb,
  p_status text
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not exists (
    select 1 from public.app_projects p
     where p.id = p_project_id and p.user_id = (select auth.uid())
  ) then
    raise exception 'project not found';
  end if;
  if (p_kind is null or p_kind not in ('openapi_http', 'postgres')) then
    raise exception 'unsupported integration kind';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 3 and 80 then
    raise exception 'invalid integration name';
  end if;
  if p_config is null or jsonb_typeof(p_config) <> 'object'
     or octet_length(p_config::text) > 300000 then
    raise exception 'invalid integration config';
  end if;
  if p_allowed_operations is null or jsonb_typeof(p_allowed_operations) <> 'array'
     or jsonb_array_length(p_allowed_operations) > 50 then
    raise exception 'invalid allowed operations';
  end if;
  if p_mapping is null or jsonb_typeof(p_mapping) <> 'array'
     or jsonb_array_length(p_mapping) > 20 then
    raise exception 'invalid mapping';
  end if;
  if (p_status is null or p_status not in ('draft', 'connected')) then
    raise exception 'invalid integration status';
  end if;

  insert into public.app_integrations (
    project_id, user_id, kind, name, status, config, allowed_operations, mapping,
    connected_at
  ) values (
    p_project_id, auth.uid(), p_kind, btrim(p_name), p_status, p_config,
    p_allowed_operations, p_mapping,
    case when p_status = 'connected' then now() else null end
  )
  returning id into v_id;

  return v_id;
end;
$$;

create or replace function public.detect_app_release_incident(
  p_check_run_id uuid,
  p_title text,
  p_severity text default 'medium'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_run public.app_release_check_runs;
  v_release public.app_releases;
  v_evidence jsonb;
  v_id uuid;
begin
  select * into v_run from public.app_release_check_runs where id = p_check_run_id;
  if not found then raise exception 'check run not found'; end if;
  if not exists (select 1 from public.app_projects p where p.id = v_run.project_id and p.user_id = v_actor) then
    raise exception 'project access denied';
  end if;
  if v_run.status <> 'failed' then raise exception 'only a failed check can open an incident'; end if;
  if (p_severity is null or p_severity not in ('low', 'medium', 'high', 'critical')) then raise exception 'invalid severity'; end if;
  if p_title is null or char_length(btrim(p_title)) not between 3 and 200 then
    raise exception 'incident title must be 3 to 200 characters';
  end if;

  select * into v_release from public.app_releases where id = v_run.release_id;
  if not found then raise exception 'release not found'; end if;

  v_evidence := jsonb_build_array(jsonb_build_object(
    'check_run_id', v_run.id,
    'name', v_run.name,
    'kind', v_run.kind,
    'status', v_run.status,
    'observed', v_run.observed,
    'detail', v_run.detail,
    'release_version', v_release.version,
    'source_revision', v_release.source_revision
  ));

  insert into public.app_release_incidents
    (project_id, release_id, deployment_id, check_run_id, user_id, title, trigger, severity, evidence)
  values
    (v_run.project_id, v_run.release_id, v_release.deployment_id, v_run.id, v_actor,
     left(btrim(p_title), 200),
     left('Configured ' || v_run.kind || ' check failed: ' || v_run.name, 500),
     p_severity, v_evidence)
  returning id into v_id;

  insert into public.app_incident_events (incident_id, project_id, user_id, kind, detail)
  values (v_id, v_run.project_id, v_actor, 'detected',
          left('Failure of ' || v_run.kind || ' check "' || v_run.name || '" recorded with redacted evidence.', 1000));

  return v_id;
end;
$$;

create or replace function public.experiment_decide_approval(
  p_approval_id uuid,
  p_decision text,
  p_note text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_approval public.experiment_approvals;
  v_role text;
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;
  if (p_decision is null or p_decision not in ('approved', 'rejected')) then
    return jsonb_build_object('ok', false, 'code', 'invalid-decision');
  end if;

  select * into v_approval
    from public.experiment_approvals
   where id = p_approval_id
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'not-found');
  end if;

  v_role := public.workspace_role(v_approval.workspace_id);
  if v_role is null or v_role not in ('owner', 'admin') then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;
  if v_approval.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'not-pending');
  end if;
  if v_approval.requested_by = v_user then
    return jsonb_build_object('ok', false, 'code', 'self-approval');
  end if;

  update public.experiment_approvals
     set status = p_decision,
         decided_by = v_user,
         decided_at = now(),
         note = left(coalesce(p_note, ''), 1000)
   where id = p_approval_id;

  insert into public.experiment_events (experiment_id, workspace_id, actor_id, kind, detail)
  values (
    v_approval.experiment_id,
    v_approval.workspace_id,
    v_user,
    'approval_' || p_decision,
    v_approval.kind || ': ' || v_approval.summary
  );

  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$$;

create or replace function public.finish_ai_request(
  p_request_id uuid,
  p_status text,
  p_error text default null,
  p_tokens_in integer default null,
  p_tokens_out integer default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_charged integer;
  v_budget_kind text;
  v_budget_id uuid;
begin
  if v_user is null then
    return;
  end if;

  if (p_status is null or p_status not in ('succeeded', 'failed')) then
    raise exception 'finish_ai_request: unsupported status %', p_status;
  end if;

  update public.ai_requests
     set status = p_status,
         error_code = nullif(left(coalesce(p_error, ''), 120), ''),
         tokens_in = coalesce(p_tokens_in, tokens_in),
         tokens_out = coalesce(p_tokens_out, tokens_out),
         finished_at = now()
   where id = p_request_id
     and user_id = v_user
     and status = 'in_flight'
  returning credits_charged, budget_kind, budget_id
       into v_charged, v_budget_kind, v_budget_id;

  if v_charged is not null and v_charged > 0 and p_status = 'failed' then
    insert into public.credit_ledger (user_id, delta, reason, request_id, note)
    values (v_user, v_charged, 'ai_release', p_request_id, 'released after a failed request')
    on conflict do nothing;

    if found and v_budget_kind is not null then
      if v_budget_kind = 'workflow' then
        update public.workflow_runs
           set credits_spent = greatest(credits_spent - v_charged, 0)
         where id = v_budget_id and user_id = v_user;
      elsif v_budget_kind = 'build' then
        update public.app_workspaces
           set credits_spent = greatest(credits_spent - v_charged, 0)
         where id = v_budget_id and user_id = v_user;
      elsif v_budget_kind = 'swarm' then
        update public.app_team_runs
           set credits_spent = greatest(credits_spent - v_charged, 0)
         where id = v_budget_id and user_id = v_user;
      end if;
    end if;
  end if;
end;
$$;

create or replace function public.knowledge_add_evidence(
  p_entry_id uuid,
  p_stance text,
  p_evidence_kind text,
  p_detail text,
  p_source_kind text default null,
  p_source_id uuid default null,
  p_observed_at date default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_entry public.knowledge_entries;
  v_id uuid;
begin
  select * into v_entry from public.knowledge_entries where id = p_entry_id;
  if v_entry.id is null then
    raise exception 'that knowledge entry does not exist';
  end if;
  if public.workspace_role(v_entry.workspace_id) is null then
    raise exception 'you are not a member of this workspace';
  end if;
  if v_entry.status <> 'active' then
    raise exception 'only the current version accepts new evidence';
  end if;
  if (p_stance is null or p_stance not in ('supports', 'contradicts')) then
    raise exception 'evidence either supports or contradicts';
  end if;
  if p_source_kind is not null
     and not public.knowledge_source_allowed(v_entry.workspace_id, p_source_kind, p_source_id) then
    raise exception 'you cannot link that record here';
  end if;

  insert into public.knowledge_evidence (
    workspace_id, entry_id, stance, evidence_kind, detail, source_kind, source_id,
    observed_at, added_by
  ) values (
    v_entry.workspace_id, p_entry_id, p_stance, p_evidence_kind, btrim(p_detail),
    p_source_kind, p_source_id, p_observed_at, v_user
  )
  returning id into v_id;

  insert into public.knowledge_events (workspace_id, entry_id, actor_id, kind, detail)
  values (v_entry.workspace_id, p_entry_id, v_user, 'evidence_recorded',
          p_stance || ':' || p_evidence_kind);

  return v_id;
end;
$$;

create or replace function public.knowledge_create_entry(
  p_workspace_id uuid,
  p_kind text,
  p_claim_type text,
  p_title text,
  p_statement text,
  p_domain text,
  p_applies_when text default '',
  p_limitations text default '',
  p_authorized_scope text default 'This workspace only; reuse elsewhere needs a transfer approval.',
  p_retention_note text default '',
  p_review_at date default null,
  p_delete_after date default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_id uuid;
begin
  if public.workspace_role(p_workspace_id) is null then
    raise exception 'you are not a member of this workspace';
  end if;
  if (p_kind is null or p_kind not in ('claim', 'procedure')) then
    raise exception 'choose claim or procedure';
  end if;
  if (p_claim_type is null or p_claim_type not in (
    'user_preference', 'project_fact', 'participant_opinion',
    'measured_observation', 'tested_procedure', 'hypothesis', 'ai_suggestion'
  )) then
    raise exception 'choose a recorded kind of statement';
  end if;
  if p_kind = 'procedure' and p_claim_type = 'project_fact' then
    raise exception 'a reusable procedure is not a project fact';
  end if;

  insert into public.knowledge_entries (
    workspace_id, created_by, owner_id, kind, claim_type, title, statement,
    domain, applies_when, limitations, authorized_scope, retention_note,
    review_at, delete_after
  ) values (
    p_workspace_id, v_user, v_user, p_kind, p_claim_type, btrim(p_title),
    btrim(p_statement), btrim(p_domain), coalesce(p_applies_when, ''),
    coalesce(p_limitations, ''), p_authorized_scope, coalesce(p_retention_note, ''),
    p_review_at, p_delete_after
  )
  returning id into v_id;

  insert into public.knowledge_events (workspace_id, entry_id, actor_id, kind, detail)
  values (p_workspace_id, v_id, v_user, 'entry_created', p_claim_type);

  return v_id;
end;
$$;

create or replace function public.knowledge_mark_impact(
  p_entry_id uuid,
  p_target_kind text,
  p_target_id uuid,
  p_target_label text,
  p_note text default ''
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_entry public.knowledge_entries;
  v_id uuid;
begin
  select * into v_entry from public.knowledge_entries where id = p_entry_id;
  if v_entry.id is null then
    raise exception 'that knowledge entry does not exist';
  end if;
  if public.workspace_role(v_entry.workspace_id) is null then
    raise exception 'you are not a member of this workspace';
  end if;
  if (p_target_kind is null or p_target_kind not in (
    'recommendation', 'contract_criterion', 'plan_task', 'improvement', 'app_change', 'other'
  )) then
    raise exception 'choose what was built on this entry';
  end if;

  insert into public.knowledge_impacts (
    workspace_id, entry_id, target_kind, target_id, target_label, note, created_by,
    invalidated_at, invalidated_reason
  ) values (
    v_entry.workspace_id, p_entry_id, p_target_kind, p_target_id, btrim(p_target_label),
    coalesce(p_note, ''), v_user,
    case when v_entry.status = 'retracted' or v_entry.verification_status = 'retracted'
         then now() else null end,
    case when v_entry.status = 'retracted' or v_entry.verification_status = 'retracted'
         then 'linked to an entry that is no longer valid' else null end
  )
  returning id into v_id;

  insert into public.knowledge_events (workspace_id, entry_id, actor_id, kind, detail)
  values (v_entry.workspace_id, p_entry_id, v_user, 'impact_linked', p_target_kind);

  return v_id;
end;
$$;

create or replace function public.knowledge_record_correction(
  p_entry_id uuid,
  p_kind text,
  p_detail text,
  p_proposed_statement text default ''
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_entry public.knowledge_entries;
  v_id uuid;
begin
  select * into v_entry from public.knowledge_entries where id = p_entry_id;
  if v_entry.id is null then
    raise exception 'that knowledge entry does not exist';
  end if;
  if public.workspace_role(v_entry.workspace_id) is null then
    raise exception 'you are not a member of this workspace';
  end if;
  if (p_kind is null or p_kind not in ('correction', 'dispute')) then
    raise exception 'choose correction or dispute';
  end if;
  if char_length(btrim(coalesce(p_detail, ''))) < 10 then
    raise exception 'explain what is wrong';
  end if;
  if p_kind = 'correction'
     and char_length(btrim(coalesce(p_proposed_statement, ''))) < 15 then
    raise exception 'a correction proposes the replacement wording';
  end if;

  insert into public.knowledge_corrections (
    workspace_id, entry_id, requested_by, kind, detail, proposed_statement
  ) values (
    v_entry.workspace_id, p_entry_id, v_user, p_kind, btrim(p_detail),
    coalesce(p_proposed_statement, '')
  )
  returning id into v_id;

  insert into public.knowledge_events (workspace_id, entry_id, actor_id, kind, detail)
  values (v_entry.workspace_id, p_entry_id, v_user, 'correction_' || p_kind, '');

  return v_id;
end;
$$;

create or replace function public.mission_control_decide_approval(
  p_approval_id uuid,
  p_decision text,
  p_note text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_approval public.mission_approvals;
begin
  if v_actor is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  select * into v_approval from public.mission_approvals
   where id = p_approval_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'not-found');
  end if;
  if (public.workspace_role(v_approval.workspace_id) is null or public.workspace_role(v_approval.workspace_id) not in ('owner', 'admin')) then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;
  if v_approval.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'already-decided');
  end if;
  if (p_decision is null or p_decision not in ('approved', 'rejected')) then
    return jsonb_build_object('ok', false, 'code', 'invalid-decision');
  end if;
  if v_approval.requested_by is not null and v_approval.requested_by = v_actor then
    return jsonb_build_object('ok', false, 'code', 'self-approval');
  end if;

  update public.mission_approvals
     set status = p_decision,
         decided_by = v_actor,
         decided_at = now(),
         note = left(coalesce(p_note, ''), 1000)
   where id = p_approval_id;

  insert into public.mission_events (mission_id, workspace_id, actor_id, kind, detail)
  values (
    v_approval.mission_id, v_approval.workspace_id, v_actor,
    'approval.' || p_decision,
    left(v_approval.kind || ': ' || v_approval.summary, 1000)
  );

  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$$;

create or replace function public.mission_control_finish_job(
  p_job_id uuid,
  p_status text,
  p_note text default '',
  p_output jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_job public.mission_agent_jobs;
  v_terminal boolean;
begin
  if v_actor is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  select * into v_job from public.mission_agent_jobs where id = p_job_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'not-found');
  end if;
  if (public.workspace_role(v_job.workspace_id) is null or public.workspace_role(v_job.workspace_id) not in ('owner', 'admin')) then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;
  if (p_status is null or p_status not in ('completed', 'failed', 'cancelled')) then
    return jsonb_build_object('ok', false, 'code', 'invalid-status');
  end if;
  if v_job.status in ('completed', 'cancelled') then
    return jsonb_build_object('ok', false, 'code', 'already-terminal', 'status', v_job.status);
  end if;

  update public.mission_agent_jobs
     set status = p_status,
         output = coalesce(p_output, output),
         error = case when p_status = 'failed' then left(coalesce(nullif(btrim(p_note), ''), 'The job failed.'), 1000) else null end,
         blocker = case when p_status = 'failed' then left(coalesce(nullif(btrim(p_note), ''), 'The job failed.'), 500) else null end,
         runtime_seconds = greatest(
           runtime_seconds,
           case when started_at is null then runtime_seconds
                else floor(extract(epoch from now() - started_at))::integer end
         ),
         finished_at = now()
   where id = v_job.id;

  if p_status = 'failed' then
    with recursive downstream(id) as (
      select d.job_id
        from public.mission_job_dependencies d
       where d.depends_on_job_id = v_job.id
      union
      select d.job_id
        from public.mission_job_dependencies d
        join downstream x on d.depends_on_job_id = x.id
    )
    update public.mission_agent_jobs j
       set status = 'blocked',
           blocker = left('Paused because dependency "' || v_job.title || '" failed.', 500),
           finished_at = null
     where j.id in (select id from downstream)
       and j.status in ('queued', 'blocked', 'running', 'awaiting_review');
  elsif p_status = 'cancelled' then
    with recursive downstream(id) as (
      select d.job_id
        from public.mission_job_dependencies d
       where d.depends_on_job_id = v_job.id
      union
      select d.job_id
        from public.mission_job_dependencies d
        join downstream x on d.depends_on_job_id = x.id
    )
    update public.mission_agent_jobs j
       set status = 'cancelled',
           error = 'Cancelled because an upstream job was cancelled.',
           finished_at = now()
     where j.id in (select id from downstream)
       and j.status in ('queued', 'blocked', 'running', 'awaiting_review');
  end if;

  insert into public.mission_events (mission_id, workspace_id, actor_id, kind, detail)
  values (
    v_job.mission_id, v_job.workspace_id, v_actor,
    'job.' || p_status,
    left('Job ' || p_status || ': ' || v_job.title ||
         case when btrim(coalesce(p_note, '')) = '' then '' else ' — ' || btrim(p_note) end, 1000)
  );

  return jsonb_build_object('ok', true, 'status', p_status);
end;
$$;

create or replace function public.orchestration_decide_checkpoint(
  p_checkpoint_id uuid,
  p_decision text,
  p_note text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_row public.orchestration_checkpoints;
  v_role text;
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;
  if (p_decision is null or p_decision not in ('approved', 'rejected')) then
    return jsonb_build_object('ok', false, 'code', 'invalid-decision');
  end if;

  select * into v_row from public.orchestration_checkpoints where id = p_checkpoint_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'not-found');
  end if;

  v_role := public.workspace_role(v_row.workspace_id);
  if v_role is null or v_role not in ('owner', 'admin') then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;
  if v_row.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'not-pending');
  end if;
  if v_row.requested_by = v_user then
    return jsonb_build_object('ok', false, 'code', 'self-approval');
  end if;

  update public.orchestration_checkpoints
     set status = p_decision,
         decided_by = v_user,
         decided_at = now(),
         note = left(coalesce(p_note, ''), 1000)
   where id = p_checkpoint_id;

  insert into public.orchestration_events (orchestration_id, workspace_id, actor_id, kind, detail)
  values (
    v_row.orchestration_id, v_row.workspace_id, v_user,
    'checkpoint_' || p_decision, v_row.kind || ': ' || v_row.title
  );

  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$$;

create or replace function public.orchestration_record_review(
  p_id uuid,
  p_decision text,
  p_built text default '',
  p_verified text default '',
  p_failed text default '',
  p_unknown text default '',
  p_deviations text default '',
  p_next_steps text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_row public.orchestrations;
  v_role text;
  v_contract public.orchestration_contracts;
  v_unverified integer;
  v_failed integer;
  v_existing text;
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;
  if (p_decision is null or p_decision not in ('accept', 'revise', 'new_contract', 'stop')) then
    return jsonb_build_object('ok', false, 'code', 'invalid-decision');
  end if;

  select * into v_row from public.orchestrations where id = p_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'not-found');
  end if;

  v_role := public.workspace_role(v_row.workspace_id);
  if v_role is null then
    return jsonb_build_object('ok', false, 'code', 'forbidden');
  end if;

  select decision into v_existing
    from public.orchestration_reviews where orchestration_id = p_id;
  if v_existing is not null and (v_existing is null or v_existing <> 'undecided') then
    return jsonb_build_object('ok', false, 'code', 'already-decided');
  end if;

  select * into v_contract from public.orchestration_contracts
   where id = v_row.current_contract_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'contract-not-approved');
  end if;

  select count(*) into v_unverified
    from jsonb_array_elements(v_contract.content->'acceptance_criteria') c
   where not exists (
     select 1 from public.orchestration_evidence e
      where e.orchestration_id = p_id
        and e.criterion_key = c->>'key'
        and e.result = 'pass'
        and e.kind not in ('ai_proposal', 'participant_opinion', 'unverified_claim')
   );

  select count(*) into v_failed
    from public.orchestration_evidence e
   where e.orchestration_id = p_id and e.result = 'fail';

  if p_decision = 'accept' then
    if v_unverified > 0 then
      return jsonb_build_object('ok', false, 'code', 'unverified');
    end if;
    if v_failed > 0 then
      return jsonb_build_object('ok', false, 'code', 'failure-unresolved');
    end if;
    if char_length(btrim(coalesce(p_verified, ''))) < 5 then
      return jsonb_build_object('ok', false, 'code', 'missing-verified');
    end if;
  end if;

  if char_length(btrim(coalesce(p_unknown, ''))) < 5 then
    return jsonb_build_object('ok', false, 'code', 'missing-unknowns');
  end if;

  insert into public.orchestration_reviews (
    orchestration_id, workspace_id, decision, built, verified, failed, unknown,
    deviations, next_steps, spent_micros, decided_by, decided_at
  ) values (
    p_id, v_row.workspace_id, p_decision,
    left(coalesce(p_built, ''), 3000),
    left(coalesce(p_verified, ''), 3000),
    left(coalesce(p_failed, ''), 3000),
    left(coalesce(p_unknown, ''), 3000),
    left(coalesce(p_deviations, ''), 3000),
    left(coalesce(p_next_steps, ''), 3000),
    v_row.consumed_micros, v_user, now()
  )
  on conflict (orchestration_id) do update
    set decision = excluded.decision,
        built = excluded.built,
        verified = excluded.verified,
        failed = excluded.failed,
        unknown = excluded.unknown,
        deviations = excluded.deviations,
        next_steps = excluded.next_steps,
        spent_micros = excluded.spent_micros,
        decided_by = excluded.decided_by,
        decided_at = excluded.decided_at
    where public.orchestration_reviews.decision = 'undecided';

  update public.orchestrations
     set status = case p_decision
       when 'accept' then 'completed'
       when 'stop' then 'stopped'
       else 'needs_revision'
     end
   where id = p_id;

  insert into public.orchestration_events (orchestration_id, workspace_id, actor_id, kind, detail)
  values (p_id, v_row.workspace_id, v_user, 'review_' || p_decision, 'A person recorded the outcome decision.');

  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$$;

create or replace function public.prepare_app_incident_recovery(
  p_incident_id uuid,
  p_kind text,
  p_plan jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_incident public.app_release_incidents;
  v_steps jsonb;
  v_limitations jsonb;
  v_standard text;
begin
  select * into v_incident from public.app_release_incidents where id = p_incident_id;
  if not found then raise exception 'incident not found'; end if;
  if not exists (select 1 from public.app_projects p where p.id = v_incident.project_id and p.user_id = v_actor) then
    raise exception 'project access denied';
  end if;
  if v_incident.status <> 'diagnosed' then raise exception 'propose a diagnosis before preparing recovery'; end if;
  if (p_kind is null or p_kind not in ('patch', 'code_rollback', 'config_rollback', 'database_recovery')) then
    raise exception 'invalid recovery kind';
  end if;
  if p_plan is null or jsonb_typeof(p_plan) <> 'object' then raise exception 'a recovery plan is required'; end if;
  v_steps := coalesce(p_plan->'steps', '[]'::jsonb);
  v_limitations := coalesce(p_plan->'limitations', '[]'::jsonb);
  if jsonb_typeof(v_steps) <> 'array' or jsonb_array_length(v_steps) = 0 then
    raise exception 'a recovery plan needs at least one step';
  end if;
  if jsonb_typeof(v_limitations) <> 'array' or jsonb_array_length(v_limitations) = 0 then
    raise exception 'a recovery plan must state its limitations';
  end if;

  v_standard := case p_kind
    when 'patch' then 'A patch is prepared but not deployed; deployment remains a separate approval.'
    when 'code_rollback' then 'Application code rollback does not reverse a database migration or restore deleted data.'
    when 'config_rollback' then 'Configuration rollback changes only configuration; it does not undo a code or database change.'
    else 'Database recovery is a separate operation; restoring a backup or applying a forward fix may lose data written after the recovery point.'
  end;
  v_limitations := v_limitations || jsonb_build_array(v_standard);

  update public.app_release_incidents
     set recovery_kind = p_kind,
         recovery_plan = jsonb_set(p_plan, '{limitations}', v_limitations),
         status = 'awaiting_approval',
         requested_at = now()
   where id = p_incident_id;

  insert into public.app_incident_events (incident_id, project_id, user_id, kind, detail)
  values (p_incident_id, v_incident.project_id, v_actor, 'recovery_prepared',
          left('Prepared a ' || replace(p_kind, '_', ' ') || ' plan and requested approval. No action was executed.', 1000));

  return jsonb_build_object('ok', true, 'status', 'awaiting_approval');
end;
$$;

create or replace function public.record_app_integration_test(
  p_id uuid,
  p_status text,
  p_note text
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if (p_status is null or p_status not in ('passed', 'failed')) then
    raise exception 'invalid test status';
  end if;

  update public.app_integrations
     set last_tested_at = now(),
         last_test_status = p_status,
         last_test_note = left(coalesce(p_note, ''), 500),
         status = case when p_status = 'failed' then 'error' else 'connected' end,
         updated_at = now()
   where id = p_id
     and user_id = (select auth.uid());
  if not found then
    raise exception 'not allowed';
  end if;
end;
$$;

create or replace function public.review_app_changeset(
  p_changeset_id uuid,
  p_decision text,
  p_note text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_changeset public.app_changesets;
  v_role text;
begin
  select * into v_changeset from public.app_changesets where id = p_changeset_id;
  if not found then raise exception 'changeset not found'; end if;
  v_role := public.app_project_role(v_changeset.project_id);
  if v_role is null or v_role not in ('owner', 'maintainer', 'reviewer') then
    raise exception 'reviewer access required';
  end if;
  if v_actor = v_changeset.author_id then raise exception 'you cannot review your own changeset'; end if;
  if v_changeset.status <> 'in_review' then raise exception 'this changeset is not awaiting review'; end if;
  if (p_decision is null or p_decision not in ('approve', 'request_changes')) then raise exception 'invalid review decision'; end if;
  if p_note is null or char_length(p_note) > 2000 then raise exception 'review note is too long'; end if;

  if p_decision = 'approve' then
    update public.app_changesets
       set status = 'approved', reviewed_digest = content_digest,
           approved_by = v_actor, approved_at = now()
     where id = p_changeset_id;
  else
    update public.app_changesets
       set status = 'rejected', reviewed_digest = null,
           approved_by = null, approved_at = null
     where id = p_changeset_id;
  end if;

  update public.app_changeset_reviews
     set status = case when p_decision = 'approve' then 'approved' else 'changes_requested' end,
         reviewer_id = v_actor,
         note = left(coalesce(p_note, ''), 2000),
         decided_at = now()
   where id = (
     select id from public.app_changeset_reviews
      where changeset_id = p_changeset_id and status = 'pending'
      order by created_at desc limit 1
   );

  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$$;

create or replace function public.save_app_integration_selection(
  p_id uuid,
  p_allowed_operations jsonb,
  p_mapping jsonb,
  p_config jsonb,
  p_status text
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_allowed_operations is null or jsonb_typeof(p_allowed_operations) <> 'array'
     or jsonb_array_length(p_allowed_operations) > 50 then
    raise exception 'invalid allowed operations';
  end if;
  if p_mapping is null or jsonb_typeof(p_mapping) <> 'array'
     or jsonb_array_length(p_mapping) > 20 then
    raise exception 'invalid mapping';
  end if;
  if p_config is null or jsonb_typeof(p_config) <> 'object'
     or octet_length(p_config::text) > 300000 then
    raise exception 'invalid integration config';
  end if;
  if (p_status is null or p_status not in ('draft', 'connected')) then
    raise exception 'invalid integration status';
  end if;

  update public.app_integrations
     set allowed_operations = p_allowed_operations,
         mapping = p_mapping,
         config = p_config,
         status = p_status,
         connected_at = case when p_status = 'connected' then coalesce(connected_at, now()) else connected_at end,
         disconnected_at = null,
         updated_at = now()
   where id = p_id
     and user_id = (select auth.uid());
  if not found then
    raise exception 'not allowed';
  end if;
end;
$$;

create or replace function public.save_env_value(
  p_project_id uuid,
  p_environment text,
  p_name text,
  p_visibility text,
  p_secret_sealed text
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if (p_environment is null or p_environment not in ('preview', 'production')) then
    raise exception 'invalid environment';
  end if;
  if (p_visibility is null or p_visibility not in ('public', 'server')) then
    raise exception 'invalid visibility';
  end if;
  if p_name !~ '^[A-Z][A-Z0-9_]{0,63}$' then
    raise exception 'invalid name';
  end if;
  if not exists (
    select 1
      from public.app_projects p
     where p.id = p_project_id
       and p.user_id = auth.uid()
  ) then
    raise exception 'not allowed';
  end if;

  insert into public.app_env_values (
    project_id, user_id, environment, name, visibility, secret_sealed
  ) values (
    p_project_id, auth.uid(), p_environment, p_name, p_visibility,
    p_secret_sealed
  )
  on conflict (project_id, environment, name) do update set
    visibility = excluded.visibility,
    secret_sealed = excluded.secret_sealed,
    updated_at = now();
end;
$$;

create or replace function public.save_provider_connection(
  p_project_id uuid,
  p_provider text,
  p_status text,
  p_account_label text,
  p_external_ref text,
  p_scope_label text,
  p_metadata jsonb,
  p_secret_sealed text
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if (p_provider is null or p_provider not in ('github', 'vercel', 'supabase')) then
    raise exception 'invalid provider';
  end if;
  if (p_status is null or p_status <> 'connected') then
    raise exception 'invalid status';
  end if;
  if not exists (
    select 1
      from public.app_projects p
     where p.id = p_project_id
       and p.user_id = auth.uid()
  ) then
    raise exception 'not allowed';
  end if;

  insert into public.app_provider_connections (
    project_id, user_id, provider, status, account_label, external_ref,
    scope_label, metadata, secret_sealed, connected_at, revoked_at
  ) values (
    p_project_id, auth.uid(), p_provider, p_status, p_account_label,
    p_external_ref, p_scope_label, coalesce(p_metadata, '{}'::jsonb),
    p_secret_sealed, now(), null
  )
  on conflict (project_id, provider) do update set
    user_id = excluded.user_id,
    status = excluded.status,
    account_label = excluded.account_label,
    external_ref = excluded.external_ref,
    scope_label = excluded.scope_label,
    metadata = excluded.metadata,
    secret_sealed = excluded.secret_sealed,
    connected_at = excluded.connected_at,
    revoked_at = null,
    updated_at = now();
end;
$$;

create or replace function public.start_workflow_run(p_workflow_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_workflow public.workflows;
  v_version public.workflow_versions;
  v_run uuid;
  v_steps jsonb;
  v_step jsonb;
  v_position integer := 0;
  v_first_kind text;
  v_kind text;
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  select * into v_workflow
    from public.workflows
   where id = p_workflow_id and user_id = v_user;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'no-workflow');
  end if;

  select * into v_version
    from public.workflow_versions
   where workflow_id = p_workflow_id and version = v_workflow.current_version;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'no-version');
  end if;

  v_steps := v_version.steps;

  if jsonb_typeof(v_steps) <> 'array'
     or jsonb_array_length(v_steps) < 2
     or jsonb_array_length(v_steps) > 10 then
    return jsonb_build_object('ok', false, 'code', 'invalid-steps');
  end if;

  insert into public.workflow_runs (
    user_id, workflow_id, workflow_name, workflow_version, goal_id, status
  )
  values (
    v_user, v_workflow.id, v_workflow.name, v_workflow.current_version,
    v_workflow.goal_id, 'waiting_for_input'
  )
  returning id into v_run;

  for v_step in select * from jsonb_array_elements(v_steps)
  loop
    v_position := v_position + 1;
    v_kind := v_step ->> 'kind';

    if (v_kind is null or v_kind not in ('user_input', 'ai_draft', 'user_review', 'connector_action', 'checkpoint')) then
      raise exception 'unsupported workflow step kind: %', v_kind
        using errcode = 'check_violation';
    end if;

    insert into public.workflow_run_steps (
      run_id, user_id, position, kind, title, instructions, config, retry_policy, status
    )
    values (
      v_run,
      v_user,
      v_position,
      v_kind,
      coalesce(nullif(btrim(v_step ->> 'title'), ''), 'Step ' || v_position),
      nullif(btrim(coalesce(v_step ->> 'instructions', '')), ''),
      coalesce(v_step -> 'config', '{}'::jsonb),
      case when v_step ->> 'retry_policy' = 'none' then 'none' else 'manual' end,
      case when v_position = 1 then 'waiting_for_input' else 'pending' end
    );
  end loop;

  select kind into v_first_kind
    from public.workflow_run_steps
   where run_id = v_run and position = 1;

  update public.workflow_runs
     set current_position = 1,
         status = case
           when v_first_kind = 'user_input' then 'waiting_for_input'
           when v_first_kind = 'ai_draft' then 'running'
           else 'waiting_for_approval'
         end
   where id = v_run;

  return jsonb_build_object('ok', true, 'run_id', v_run);
end;
$$;
